const D = { es: ES, en: EN, pt: PT };

export function t(s, vars) {
  let r = (D[cur] && D[cur][s]) || ES[s] || s;
  if (vars) r = r.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');
  return r;
}

