export function langName(code) {
  if (!code || code === 'und') return t('Idioma') + ' ?';
  try { const n = new Intl.DisplayNames([cur], { type: 'language' }).of(code); return n ? n[0].toUpperCase() + n.slice(1) : code; }
  catch { return code; }
}

